@startuml

class User {
  + UserID : int
  + Name : string
  + Email : string
  + Birthdate : date
}

class Account {
  + AccountNumber : int
  + Type : string
  + MonthlyFee : double
}

class PersonalAccount {}

class BusinessAccount {
  + CompanyName : string
}

class Page {
  + PageName : string
  + Visits : int
}

class AdvertisementPage {
  + BounceRate : double
  + ClickThroughRate : double
  + ConversionRate : double
}

User "1" -- "*" Account
Account "0..*" -- "1" User
Account "1" -- "*" Page
Page "1" -- "1" Account
PersonalAccount --|> Account
BusinessAccount --|> Account

@enduml

